package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_1 : Real;
    in attribute io_2 : Real;
    in attribute io_3 : Boolean;
    attribute manualMode : Boolean := false;
    attribute previousPressed : Boolean := false;
    perform action tick {
      first start;
      then if ((io_3) and ((not previousPressed))) {
        first start;
        then assign manualMode := (not manualMode);
      }
      then assign previousPressed := io_3;
    }
    out attribute io_0 : Real = (if manualMode ? io_1 else io_2);
    out attribute io_4 : Integer = (if manualMode ? (if ((io_1) >= (0.0)) ? 1 else 0) else (if ((io_2) >= (0.0)) ? 1 else 0));
  }
  part system : Controller;
}
